		if (!value) continue;
		try {
			const proxyUrl = new URL(value);
			if ((proxyUrl.protocol === "http:" || proxyUrl.protocol === "https:") && proxyUrl.hostname) return value;
		} catch {
			// Invalid proxy env vars should not weaken local DNS SSRF checks.
		}
	}
	return "";
}

